import { createLocalGhTransport, createRedactor, collectSentinels, evidenceSlug, readEvidenceFile, mintAppJwt } from './policy-commissioning.mjs';
import { isDirectEntry } from './direct-entry.mjs';
import { REPOSITORY, WORKFLOW_PATH, WORKFLOW_NAME, WORKFLOW_FILE, JOHN, CONTROLS, ENVIRONMENTS, ReviewerRefusal, refuse, closed, id, sha, hash, time, order, fileRef, retained, retain, json, digest, canonical, user, installation, original, environmentPair, intent, probe, state, baseline, capture, readCapture, assertWorkflow, reviewerEvent, replay, fixedReviewBody, diagnosticResult } from './reviewer-negative-probe.mjs';

export const PHASES=Object.freeze(['stage-self','dispatch-self','collect-self','cancel-self','stage-app','dispatch-app','collect-app','cancel-app','assess']);
const APP=Object.freeze({kind:'AppInstallation',app_id:'5043150',app_slug:'aios-reviewer-diagnostic',installation_id:'163986129',account_id:'293764221',account_login:'aiosbrain',repository_id:'1268462466'});
const API=`/repos/${REPOSITORY}`;
const JSON_LIMIT=64*1024, RAW_LIMIT=1024*1024, TOTAL_LIMIT=32*1024*1024;
const DEADLINE_MS=10*60_000,CANCEL_MS=2*60_000,SLOT_MS=15_000;
const nowISO=(now)=>now().toISOString();
const kindFor=(control)=>control===CONTROLS[0]?'reviewer-self':control===CONTROLS[1]?'reviewer-app':refuse('unknown reviewer control');
const ms=(value)=>Date.parse(value);
const name=(run,attempt,control,kind,n=0)=>`reviewer-${run}-${attempt}-${control==='self_review_refused'?'self':'app'}-${kind}${n?`-${String(n).padStart(3,'0')}`:''}.json`;
const readName=(r,a,c,k)=>name(r,a,c,k);
function nextName(s,kind,ext='json'){let n=1;for(;;n++){const candidate=name(s.runId,s.attempt,s.control,kind,n).replace(/\.json$/,`.${ext}`);if(!readdirSync(s.dir).includes(candidate))return candidate;}}
function writeJson(s,kind,value){const bytes=Buffer.from(`${canonical(value)}\n`);return retain(s.dir,nextName(s,kind),bytes,JSON_LIMIT);}
function writeRaw(s,kind,value,max=RAW_LIMIT){const bytes=Buffer.isBuffer(value)?value:Buffer.from(value);return retain(s.dir,nextName(s,kind,'raw'),bytes,max);}
function bodyOf(response){if(response.complete!==true||typeof response.raw_text!=='string')refuse('provider response bytes were not retained');return Buffer.from(response.raw_text);}
function boundedBundle(dir){let total=0;for(const entry of readdirSync(dir)){if(!entry.startsWith('reviewer-'))continue;const p=path.join(dir,entry);try{const b=readFileSync(p);total+=b.length;}catch{refuse('diagnostic bundle has unreadable entry');}if(total>TOTAL_LIMIT)refuse('diagnostic bundle exceeds 32 MiB');}}

/** The only routable provider paths. No caller URL, environment, ref or principal selects an endpoint. */
export function fixedRead(route,{runId=null,workflowId=null,environment=null,installationId=APP.installation_id,page=null}={}){
 const paged=(base,extra='')=>{if(!Number.isInteger(page)||page<1||page>10)refuse('page bound');return `${base}${base.includes('?')?'&':'?'}${extra}per_page=100&page=${page}`;};
 const run=()=>{id(runId);return `${API}/actions/runs/${runId}`;};
 switch(route){
 case 'repository':return API;case 'staging-ref':return `${API}/git/ref/heads/staging`;
 case 'workflow':return `${API}/actions/workflows/${WORKFLOW_FILE}`;
 case 'probe-runs':id(workflowId);return paged(`${API}/actions/workflows/${workflowId}/runs`,'event=workflow_dispatch&branch=staging&');
 case 'run-attempt':return `${run()}/attempts/1`;case 'run-latest':return run();
 case 'jobs':return paged(`${run()}/attempts/1/jobs`);case 'pending':return `${run()}/pending_deployments`;
 case 'approvals':return `${run()}/approvals`;
 case 'environment':if(!ENVIRONMENTS.some(e=>e.name===environment))refuse('unknown environment');return `${API}/environments/${environment}`;
 case 'branches':if(!ENVIRONMENTS.some(e=>e.name===environment))refuse('unknown environment');return paged(`${API}/environments/${environment}/deployment-branch-policies`);
 case 'hooks-projection':return paged(`${API}/hooks`);
 case 'app':return '/app';case 'installation':if(installationId!==APP.installation_id)refuse('installation differs');return `/app/installations/${installationId}`;
 case 'token-repositories':return paged('/installation/repositories');
 default:refuse('unsupported reviewer read');
 }
}
export function fixedMutation(action,{runId=null,environmentId=null,repositoryId=APP.repository_id}={}){
 switch(action){
 case 'dispatch':return {method:'POST',path:`${API}/actions/workflows/${WORKFLOW_FILE}/dispatches`,body:{ref:'staging'}};
 case 'review':id(runId);id(environmentId);return {method:'POST',path:`${API}/actions/runs/${runId}/pending_deployments`,body:fixedReviewBody(environmentId)};
 case 'cancel':id(runId);return {method:'POST',path:`${API}/actions/runs/${runId}/cancel`,body:null};
 case 'token-issue':id(repositoryId);return {method:'POST',path:`/app/installations/${APP.installation_id}/access_tokens`,body:{repository_ids:[Number(repositoryId)],permissions:{deployments:'write'}}};
 case 'token-revoke':return {method:'DELETE',path:'/installation/token',body:null};
 default:refuse('unsupported reviewer mutation');
 }
}
export function makeBoundary({observer,appJwt=null,appToken=null}){return async(role,method,route,ctx={},body=null)=>{
 if(!['observer','app-jwt','app-token'].includes(role))refuse('unknown principal role');
 if(route==='hooks-projection')refuse('hooks require the projection-only adapter');
 if(role==='observer'&&['app','installation','token-repositories','token-issue','token-revoke','review'].includes(route))refuse('App mutation/identity cannot use John session');
 if(role==='app-jwt'&&!['app','installation','token-issue'].includes(route))refuse('App JWT may only identify and mint');
 if(role==='app-token'&&!['token-repositories','token-revoke','review'].includes(route))refuse('installation token cannot substitute for observer/JWT');
 let target;
 if(method==='GET'){target=fixedRead(route,ctx);}else{const m=fixedMutation(route,ctx);if(m.method!==method||canonical(m.body)!==canonical(body))refuse('mutation body/target differs');target=m.path;}
 const transport=role==='observer'?observer:role==='app-jwt'?appJwt:appToken;
 if(typeof transport!=='function')refuse('principal transport unavailable; no fallback');
 return transport(method,target,body);
 };}

export async function captureRead(s,role,route,ctx={}){
 const started=nowISO(s.now),response=await s.request(role,'GET',route,ctx),completed=nowISO(s.now);
 if(response.complete!==true||typeof response.raw_text!=='string')refuse(`${route} response is incomplete`);
 const bytes=bodyOf(response);if(bytes.length>RAW_LIMIT)refuse(`${route} raw page exceeds bound`);
 const raw=writeRaw(s,route.replace(/[^a-z-]/g,'-'),bytes);
 const subject=ctx.runId??ctx.workflowId??(route==='repository'?s.original.repository_id:route==='workflow'||route==='environment'?(response.body?.id?String(response.body.id):null):route==='branches'?s.environments?.find(e=>e.name===ctx.environment)?.environment_id:route==='app'?APP.app_id:route==='installation'?APP.installation_id:route==='token-repositories'?APP.installation_id:null);
 const descriptor={capture_version:1,route,subject_id:subject??null,page:ctx.page??null,started_at:started,completed_at:completed,http_status:response.status,body:raw,representation:'original-json'};
 const ref=writeJson(s,`capture-${route}`,descriptor);capture(descriptor);
 if(response.status!==200)refuse(`${route} returned ${response.status}`);
 return {ref,body:response.body,descriptor};
}
async function pages(s,role,route,ctx={},key=null){const refs=[],all=[];for(let page=1;page<=10;page++){
 const x=await captureRead(s,role,route,{...ctx,page});refs.push(x.ref);const items=key?x.body?.[key]:x.body;
 if(!Array.isArray(items)||items.length>100)refuse(`${route} page is malformed`);
 all.push(...items);if(items.length<100){if(key&&Number.isSafeInteger(x.body?.total_count)&&all.length!==x.body.total_count)refuse(`${route} count is incomplete`);return {refs,items:all};}
 }refuse(`${route} exceeds 10 pages`);}
function refForExisting(dir,filename){if(!/^[A-Za-z0-9][A-Za-z0-9._-]{0,120}$/.test(filename))refuse('unsafe existing evidence name');const fd=openSync(path.join(dir,filename),constants.O_RDONLY|constants.O_NOFOLLOW);let bytes;try{const st=fstatSync(fd);if(!st.isFile()||(st.mode&0o777)!==0o600||st.size>JSON_LIMIT)refuse('existing evidence file type/mode/size invalid');bytes=readFileSync(fd);}finally{closeSync(fd);}const ref={artifact:filename,sha256:digest(bytes)};retained(dir,ref,JSON_LIMIT);return ref;}
async function assertObserver(s){const r=await s.request('observer','GET','repository');if(r.status!==200||r.body?.id!==Number(s.original.repository_id)||r.body?.full_name!==REPOSITORY||r.body?.default_branch!=='staging')refuse('repository identity/default branch changed');}
function localWorkflowSources(s){const root=path.resolve(import.meta.dirname,'../..');const listing=execFileSync('git',['ls-tree','-r','--name-only',s.original.workflow_sha,'.github/workflows'],{cwd:root,encoding:'utf8'}).trim().split('\n').filter(x=>/\.github\/workflows\/[^/]+\.ya?ml$/.test(x));if(listing.length<1||listing.length>100)refuse('workflow source count unknown');const sources=[];for(const p of listing){const bytes=execFileSync('git',['show',`${s.original.workflow_sha}:${p}`],{cwd:root,maxBuffer:RAW_LIMIT});const blobSha=execFileSync('git',['hash-object','--stdin'],{cwd:root,input:bytes,encoding:'utf8'}).trim();sha(blobSha);const body=writeRaw(s,'workflow-source',bytes);if(p===WORKFLOW_PATH)assertWorkflow(bytes.toString('utf8'));sources.push({path:p,blob_sha:blobSha,body});}if(!sources.some(x=>x.path===WORKFLOW_PATH))refuse('inert workflow absent at reviewed source');return sources;}
export function inducedTriggers(workflows,hooks){for(const item of workflows){let doc;try{doc=YAML.parse(item.text??'',{uniqueKeys:true});}catch{return 'unknown';}const events=doc?.on;if(!events||typeof events!=='object'||Array.isArray(events))return 'unknown';for(const [event,configuration] of Object.entries(events)){if(event==='workflow_run'){const names=configuration?.workflows;if(Array.isArray(names)&&names.length>0&&names.every(x=>typeof x==='string'&&x!==WORKFLOW_NAME))continue;return 'blocked';}if(['workflow_job','deployment_status','deployment','check_run','check_suite'].includes(event))return 'blocked';}}for(const h of hooks){if(h.active!==true)continue;if(h.events.some(e=>e==='*'||['workflow_run','workflow_job','deployment','deployment_status','check_run','check_suite'].includes(e)))return 'blocked';}return 'clear';}
async function hookProjection(s){if(typeof s.hooksProjection!=='function')refuse('safe hook projection adapter unavailable');const pages=[];for(let page=1;page<=10;page++){const start=nowISO(s.now);const result=await s.hooksProjection(page);const end=nowISO(s.now);if(result.status!==200||!Array.isArray(result.entries)||result.entries.length>100)refuse('hook projection incomplete');for(const h of result.entries){closed(h,['id','active','events'],'hook');id(String(h.id));if(typeof h.active!=='boolean'||!Array.isArray(h.events)||h.events.some(e=>typeof e!=='string'))refuse('hook projection invalid');}pages.push({page,started_at:start,completed_at:end,http_status:200,entries:result.entries.map(h=>({...h,id:String(h.id)}))});if(result.entries.length<100)return pages;}refuse('hook pages exceed bound');}
export async function triggerInventory(s){const staging=await captureRead(s,'observer','staging-ref');if(staging.body?.object?.sha!==s.original.workflow_sha)refuse('staging source drift');const sources=localWorkflowSources(s);const hooks=await hookProjection(s);const decision=inducedTriggers(sources.map(x=>({...x,text:retained(s.dir,x.body,RAW_LIMIT).toString('utf8')})),hooks.flatMap(x=>x.entries));const inventory={trigger_version:1,candidate_sha:s.original.workflow_sha,measured_at:nowISO(s.now),staging_ref:staging.ref,workflows:sources,hooks,decision};const ref=writeJson(s,'trigger',inventory);if(decision!=='clear')refuse('downstream workflow or hook trigger blocks dispatch');return {ref,inventory};}
function verifySameInventory(a,b){const normalize=x=>canonical({candidate_sha:x.candidate_sha,workflows:x.workflows.map(y=>({path:y.path,blob_sha:y.blob_sha,body:y.body.sha256})),hooks:x.hooks.map(y=>y.entries)});if(normalize(a)!==normalize(b))refuse('trigger inventory drift');}
async function policies(s){const out=[];for(const e of s.environments){const settings=await captureRead(s,'observer','environment',{environment:e.name});if(String(settings.body?.id)!==e.environment_id||settings.body?.name!==e.name)refuse('environment identity changed');const branches=await pages(s,'observer','branches',{environment:e.name},'branch_policies');const adminName=`reviewer-${s.runId}-${s.attempt}-${e.name}-admin-bypass.json`;const admin=refForExisting(s.dir,adminName);out.push({environment:e,settings:settings.ref,branches:branches.refs,admin_bypass_observation:admin});}return out;}
function validatePolicy(s,pair){const setting=readCapture(s.dir,pair.settings,{route:'environment'}).body;const branchPages=pair.branches.map((r,n)=>readCapture(s.dir,r,{route:'branches',page:n+1}).body);const branches=branchPages.flatMap(x=>x.branch_policies??[]);const rr=(setting.protection_rules??[]).filter(x=>x.type==='required_reviewers');const bp=(setting.protection_rules??[]).filter(x=>x.type==='branch_policy');if(rr.length!==1||bp.length!==1||rr[0].prevent_self_review!==true||canonical(rr[0].reviewers)!==canonical([{type:'User',id:5806135,login:'johnellison'}])||setting.deployment_branch_policy?.protected_branches!==false||setting.deployment_branch_policy?.custom_branch_policies!==true||branches.length!==1||branches[0].name!=='staging'||branches[0].type!=='branch')refuse('protected policy differs');const admin=json(s.dir,pair.admin_bypass_observation);if(admin?.environment!==pair.environment.name||admin?.can_admins_bypass!==false)refuse('UI-only admin bypass evidence absent');}
function parseRun(s,body,expectedRun){if(String(body?.id)!==expectedRun||String(body?.repository?.id)!==s.original.repository_id||body?.repository?.full_name!==REPOSITORY||body?.path!==WORKFLOW_PATH||body?.head_sha!==s.original.workflow_sha||body?.head_branch!=='staging'||body?.event!=='workflow_dispatch'||String(body?.run_attempt)!=='1'||String(body?.actor?.id)!==JOHN.user_id||body?.actor?.login!==JOHN.login||body?.actor?.type!=='User'||String(body?.triggering_actor?.id)!==JOHN.user_id||body?.triggering_actor?.login!==JOHN.login||body?.triggering_actor?.type!=='User')refuse('probe run producer/source/actors differ');return body;}
function parseJobs(s,p,rows,stage){if(rows.length!==2)refuse('probe must have exactly two jobs');const jobs=[];for(const env of s.environments){const j=rows.find(x=>x.name===env.job_key);if(!j||String(j.run_id)!==p.run_id||String(j.run_attempt)!=='1'||j.head_sha!==s.original.workflow_sha||j.environment!==env.name||!Number.isSafeInteger(j.id)||j.id<=0)refuse('job identity/source differs');if(!['waiting','pending','completed','queued','in_progress'].includes(j.status))refuse('unknown job status');if(stage==='pre-review'&&((j.steps??[]).length!==0||j.runner_id!==null||j.runner_name!==null))refuse('job executed or allocated runner');if(stage==='pre-review'&&j.status!=='waiting'&&j.status!=='pending')refuse('job passed protected pending gate');if(stage==='terminal'&&j.status!=='completed')refuse('job is not terminal');jobs.push({job_key:env.job_key,job_id:String(j.id),environment:env});}if(jobs[0].job_id===jobs[1].job_id)refuse('duplicate job IDs');return jobs;}
function parsePending(s,entries,stage){if(!Array.isArray(entries))refuse('pending deployment shape');const ids=entries.map(x=>String(x?.environment?.id));if(new Set(ids).size!==ids.length)refuse('duplicate pending environment');for(const x of entries){if(!s.environments.some(e=>e.environment_id===String(x?.environment?.id)&&e.name===x?.environment?.name))refuse('foreign pending environment');}if(stage==='pre-review'&&(entries.length!==2||s.environments.some(e=>!ids.includes(e.environment_id))))refuse('pending environment missing');if(stage==='terminal'&&entries.length)refuse('terminal run still pending');}
export async function collectState(s,p,stage){const start=nowISO(s.now);const originalRun=s.originalRunRef;const staging=await captureRead(s,'observer','staging-ref');if(staging.body?.object?.sha!==s.original.workflow_sha)refuse('source changed during state');const before=await captureRead(s,'observer','run-latest',{runId:p.run_id});const attempt=await captureRead(s,'observer','run-attempt',{runId:p.run_id});const jobs=await pages(s,'observer','jobs',{runId:p.run_id},'jobs');const pending=await captureRead(s,'observer','pending',{runId:p.run_id});const approvals=await captureRead(s,'observer','approvals',{runId:p.run_id});const policy=await policies(s);const after=await captureRead(s,'observer','run-latest',{runId:p.run_id});const end=nowISO(s.now);
 const doc={state_version:1,stage,observer:JOHN,started_at:start,completed_at:end,original_run:originalRun,staging_ref:staging.ref,latest_before:before.ref,attempt:attempt.ref,jobs:jobs.refs,pending:pending.ref,approvals:approvals.ref,policies:policy,latest_after:after.ref};state(doc);const ref=writeJson(s,`state-${stage}`,doc);if(ms(end)-ms(start)>15_000)refuse('state read span too long');parseRun(s,before.body,p.run_id);parseRun(s,attempt.body,p.run_id);parseRun(s,after.body,p.run_id);if(before.body.status!==after.body.status&&stage!=='terminal')refuse('run changed during state');if(before.body.run_attempt!==after.body.run_attempt||before.body.run_attempt!==attempt.body.run_attempt)refuse('rerun during state');parseJobs(s,p,jobs.items,stage);parsePending(s,pending.body,stage);if(!Array.isArray(approvals.body))refuse('approval history shape');if(stage!=='terminal'&&approvals.body.length)refuse('probe approval appeared');if(stage==='post-review'&&jobs.items.some(x=>x.status!=='waiting'&&x.status!=='pending'||(x.steps??[]).length||x.runner_id!==null))refuse('job execution after review request');for(const q of policy)validatePolicy(s,q);
 return {ref,doc,run:after.body,jobs:jobs.items,pending:pending.body,approvals:approvals.body};}
function fixedOriginal(s){const source=s.originalIntent;const o={repository:REPOSITORY,repository_id:String(source.repository_id),run_id:s.runId,attempt:s.attempt,workflow_path:'.github/workflows/release-policy-commissioning.yml',workflow_sha:String(source.workflow_sha),intent_sha256:s.originalIntentRef.sha256};original(o);return o;}
export async function openSession({runId,attempt,dir,control,now=()=>new Date(),observer=null,hooksProjection=null,appJwt=null,appToken=null}){
 id(runId);id(attempt);if(!CONTROLS.includes(control))refuse('unknown control');const root=assertPrivateDirectory(dir);const originalIntentFile=`commissioning-${evidenceSlug(runId,attempt,'intent')}.json`;const originalIntentRef=refForExisting(root,originalIntentFile);const originalIntent=readEvidenceFile(root,evidenceSlug(runId,attempt,'intent'));if(!originalIntent||originalIntent.repository!==REPOSITORY||originalIntent.workflow_path!=='.github/workflows/release-policy-commissioning.yml'||String(originalIntent.run_id)!==runId||String(originalIntent.attempt)!==attempt)refuse('original intent mismatch');
 const defaultObserver=createLocalGhTransport({spawnImpl:spawn,redact:createRedactor(collectSentinels(process.env)),retainRaw:true});const selectedObserver=observer??defaultObserver;const request=makeBoundary({observer:selectedObserver,appJwt,appToken});const s={runId,attempt,dir:root,control,now,request,observer:selectedObserver,hooksProjection,originalIntent,originalIntentRef,original:null,environments:null,originalRunRef:null};s.original=fixedOriginal(s);return s;}
function loadedIntent(s){const filename=readName(s.runId,s.attempt,s.control,'intent');const ref=refForExisting(s.dir,filename);const data=intent(json(s.dir,ref),APP);if(data.original.run_id!==s.runId||data.original.attempt!==s.attempt||data.original.intent_sha256!==s.original.intent_sha256)refuse('probe intent not linked to original');s.environments=data.environments;const base=baseline(json(s.dir,data.baseline_state));s.originalRunRef=base.original_run;return {ref,data};}
function reviewerJournal(s,intentRef,lock){return openReviewerJournal({dir:s.dir,runId:s.runId,attempt:s.attempt,kind:kindFor(s.control),intentSha256:intentRef.sha256,lock,now:s.now});}
function originalLink(s,control,intentRef,journalArtifact){const lock=acquireJournalLock({dir:s.dir,runId:s.runId,attempt:s.attempt,kind:'resource'});try{const originalJournal=openJournal({dir:s.dir,runId:s.runId,attempt:s.attempt,lock,kind:'resource',source:s.original.workflow_sha,now:s.now});const records=originalJournal.read();if(!records.length||records.some(x=>x.type==='run-closed'))refuse('original commissioning run is not active');const existing=records.filter(x=>x.type==='reviewer-probe-linked'&&x.data?.control===control);if(existing.length)refuse('reviewer control already linked');originalJournal.append('reviewer-probe-linked',{control,intent_sha256:intentRef.sha256,probe_journal_artifact:journalArtifact});const link=records.length+1;return writeJson(s,'original-link',{link_version:1,control,original_run_id:s.runId,original_attempt:s.attempt,journal_seq:link,intent_sha256:intentRef.sha256,journal_artifact:journalArtifact});}finally{lock.release();}}
function verifyOriginalLink(s,ref){const x=json(s.dir,ref);const list=readJournal({dir:s.dir,runId:s.runId,attempt:s.attempt});const r=list.find(y=>y.seq===x.journal_seq);if(!r||r.type!=='reviewer-probe-linked'||r.data?.control!==s.control||r.data?.intent_sha256!==x.intent_sha256)refuse('original reviewer link differs');return r;}
async function originalActive(s){await assertObserver(s);const x=await captureRead(s,'observer','run-latest',{runId:s.runId});if(x.body?.status==='completed'||x.body?.conclusion||String(x.body?.run_attempt)!==s.attempt||x.body?.head_sha!==s.original.workflow_sha||x.body?.path!==s.original.workflow_path)refuse('original protected run is not active at trusted source');const pending=await captureRead(s,'observer','pending',{runId:s.runId});const approvals=await captureRead(s,'observer','approvals',{runId:s.runId});if(!Array.isArray(pending.body)||pending.body.length<2||!Array.isArray(approvals.body)||approvals.body.length)refuse('original protected run already approved/not pending');s.originalRunRef=x.ref;return x;}
async function measuredEnvironments(s){const out=[];for(const e of ENVIRONMENTS){const x=await captureRead(s,'observer','environment',{environment:e.name});if(!Number.isSafeInteger(x.body?.id)||x.body.id<=0||x.body.name!==e.name)refuse('environment identity unavailable');out.push({name:e.name,environment_id:String(x.body.id),job_key:e.job_key});}environmentPair(out);return out;}
function ensureOriginalWindow(s){const j=readJournal({dir:s.dir,runId:s.runId,attempt:s.attempt});if(!j.length||j.some(x=>x.type==='run-closed'))refuse('original journal is closed');return j;}
async function baselineCapture(s){const start=nowISO(s.now);const originalRun=await originalActive(s);const staging=await captureRead(s,'observer','staging-ref');if(staging.body?.object?.sha!==s.original.workflow_sha)refuse('staging source differs');s.environments=await measuredEnvironments(s);const policy=await policies(s);policy.forEach(x=>validatePolicy(s,x));const b={baseline_version:1,observer:JOHN,captured_at:nowISO(s.now),original_run:originalRun.ref,staging_ref:staging.ref,policies:policy};baseline(b);return {ref:writeJson(s,'baseline',b),doc:b,started:start};}
async function currentWorkflow(s){const x=await captureRead(s,'observer','workflow');if(x.body?.path!==WORKFLOW_PATH||x.body?.name!==WORKFLOW_NAME||x.body?.state!=='active'||!Number.isSafeInteger(x.body?.id))refuse('probe workflow not registered/active');return {ref:x.ref,id:String(x.body.id)};}
