 try{response=await fetchImpl(`https://api.github.com${target}`,{method,redirect:'error',signal:AbortSignal.timeout(timeoutMs),headers:{Accept:'application/vnd.github+json',Authorization:`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28',...(body===null?{}:{'Content-Type':'application/json'})},body:body===null?undefined:typeof body==='string'?body:JSON.stringify(body)});}catch{return {complete:false,status:0};}
